/**
 * Archives every live issue in the batch that the actor could archive on its
 * own. Unknown ids, another organization's ids and ids that are already
 * archived are skipped and not permission-checked; one permission failure
 * rejects the call before any row is written or any event is published.
 * Duplicate ids count once, and both result lists follow first-seen order.
 */
export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
): Promise<{ archived: readonly IssueId[]; skipped: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const orderedIds: IssueId[] = [];
