import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId } from "@/types/common";

const UNKNOWN = "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId;

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("bulk-north");
  acme = await createTenant("bulk-acme");
});

afterAll(() => {
  cleanup();
});

async function insert(
  tenant: Tenant,
  title: string,
  authorRole: "owner" | "member" | "viewer" = "owner",
  assigneeRole?: "owner" | "member" | "viewer",
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, {
      title,
      assigneeId: assigneeRole === undefined ? null : tenant.userIds[assigneeRole],
    }),
    tenant.userIds[authorRole],
    number,
  );
}

describe("bulk archive issues", () => {
  it("bounds the id list at 1..50 and validates ids", () => {
    const id = UNKNOWN;
    expect(
      bulkArchiveIssuesSchema.safeParse({ orgId: north.org.id, issueIds: [] }).success,
    ).toBe(false);
    expect(
      bulkArchiveIssuesSchema.safeParse({
        orgId: north.org.id,
        issueIds: Array.from({ length: 50 }, () => id),
      }).success,
    ).toBe(true);
    expect(
      bulkArchiveIssuesSchema.safeParse({
        orgId: north.org.id,
        issueIds: Array.from({ length: 51 }, () => id),
      }).success,
    ).toBe(false);
    expect(
      bulkArchiveIssuesSchema.safeParse({ orgId: "nope", issueIds: [id] }).success,
    ).toBe(false);
    expect(
      bulkArchiveIssuesSchema.safeParse({ orgId: north.org.id, issueIds: ["nope"] }).success,
    ).toBe(false);
  });

  it("returns empty for an empty id list and includes archived rows of this org only", async () => {
    const live = await insert(north, "lookup live");
    const archived = await insert(north, "lookup archived");
    const other = await insert(acme, "lookup other");
    await issueRepo.archiveIssue(north.org.id, archived.id);

    await expect(issueRepo.findIssuesByIds(north.org.id, [])).resolves.toEqual([]);

    const found = await issueRepo.findIssuesByIds(north.org.id, [
      live.id,
      archived.id,
      other.id,
      UNKNOWN,
    ]);
    const ids = found.map((issue) => issue.id).sort();
    expect(ids).toEqual([live.id, archived.id].sort());
    expect(found.find((issue) => issue.id === archived.id)?.archivedAt).not.toBeNull();
  });

  it("archives live issues, skips the rest, and preserves first-seen order", async () => {
    const liveA = await insert(north, "live A");
    const liveB = await insert(north, "live B");
    const already = await insert(north, "already");
    const other = await insert(acme, "other org");
    const archivedRow = await issueRepo.archiveIssue(north.org.id, already.id);

    const received: Array<{ issueId: string }> = [];
    const off = subscribe("issue.archived", (payload) => {
      received.push(payload);
    });

    try {
      const result = await issueService.bulkArchiveIssues(north.actors.member, {
        orgId: north.org.id,
        issueIds: [liveB.id, UNKNOWN, liveA.id, liveB.id, already.id, other.id, UNKNOWN],
      });

      expect(result.archived).toEqual([liveB.id, liveA.id]);
      expect(result.skipped).toEqual([UNKNOWN, already.id, other.id]);
      expect(received.map((event) => event.issueId)).toEqual([liveB.id, liveA.id]);

      const untouched = await issueRepo.findIssueById(north.org.id, already.id);
      expect(untouched?.archivedAt).toBe(archivedRow.archivedAt);
      expect(untouched?.updatedAt).toBe(archivedRow.updatedAt);

      const archivedA = await issueRepo.findIssueById(north.org.id, liveA.id);
      expect(archivedA?.archivedAt).not.toBeNull();
      expect(archivedA?.archivedAt).toBe(archivedA?.updatedAt);
    } finally {
      off();
    }
  });

  it("lets a viewer archive issues they authored or are assigned to", async () => {
    const authored = await insert(north, "viewer authored", "viewer");
    const assigned = await insert(north, "viewer assigned", "owner", "viewer");

    const result = await issueService.bulkArchiveIssues(north.actors.viewer, {
      orgId: north.org.id,
      issueIds: [authored.id, assigned.id],
    });

    expect(result).toEqual({ archived: [authored.id, assigned.id], skipped: [] });
  });

  it("rejects the whole call when any live issue is forbidden", async () => {
    const allowed = await insert(north, "viewer owns", "viewer");
    const forbidden = await insert(north, "someone else", "member");
    const received: unknown[] = [];
    const off = subscribe("issue.archived", (payload) => {
      received.push(payload);
    });

    try {
      await expect(
        issueService.bulkArchiveIssues(north.actors.viewer, {
          orgId: north.org.id,
          issueIds: [allowed.id, forbidden.id],
        }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);

      const stillLive = await issueRepo.findIssueById(north.org.id, allowed.id);
      expect(stillLive?.archivedAt).toBeNull();
      expect(received).toEqual([]);
    } finally {
      off();
    }
  });

  it("does not permission-check skipped ids", async () => {
    const allowed = await insert(north, "viewer owns again", "viewer");
    const already = await insert(north, "archived by someone else", "member");
    const before = await issueRepo.archiveIssue(north.org.id, already.id);

    const result = await issueService.bulkArchiveIssues(north.actors.viewer, {
      orgId: north.org.id,
      issueIds: [already.id, allowed.id, UNKNOWN],
    });

    expect(result).toEqual({
      archived: [allowed.id],
      skipped: [already.id, UNKNOWN],
    });
    const after = await issueRepo.findIssueById(north.org.id, already.id);
    expect(after?.archivedAt).toBe(before.archivedAt);
    expect(after?.updatedAt).toBe(before.updatedAt);
  });

  it("rejects a different organization before touching rows", async () => {
    const issue = await insert(north, "stay live");
    await expect(
      issueService.bulkArchiveIssues(acme.actors.owner, {
        orgId: north.org.id,
        issueIds: [issue.id],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const still = await issueRepo.findIssueById(north.org.id, issue.id);
    expect(still?.archivedAt).toBeNull();
  });
});

